   607	func gitLines(ctx context.Context, repoRoot string, args ...string) ([]string, error) {
   608		full := append([]string{"-C", repoRoot}, args...)
   609		output, err := exec.CommandContext(ctx, "git", full...).Output()
   610		if err != nil {
   611			return nil, fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
   612		}
   613		trimmed := strings.TrimSpace(string(output))
   614		if trimmed == "" {
   615			return nil, nil
   616		}
   617		lines := strings.Split(trimmed, "\n")
   618		result := lines[:0]
   619		for _, line := range lines {
   620			if line = strings.TrimSpace(line); line != "" {
   621				result = append(result, line)
   622			}
   623		}
   624		return result, nil
   625	}
