   800	// detectReviewScope runs a handful of cheap `git` queries to describe the
   801	// set of changes the user is about to review. Best-effort: any individual
   802	// query that fails leaves the corresponding field at its zero value.
   803	func detectReviewScope(ctx context.Context) (reviewScope, error) {
   804		repoRoot, err := paths.WorktreeRoot(ctx)
   805		if err != nil {
   806			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
   807		}
   808		var s reviewScope
   809		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
   810		if s.Branch == detachedHEADDisplay {
   811			s.Branch = ""
   812		}
   813		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
   814		base := detectBaseBranchRef(ctx, repoRoot)
   815		s.Base = base.display
   816		s.BaseRef = base.ref
   817		headRef := s.Branch
   818		if headRef == "" {
   819			headRef = detachedHEADDisplay
   820		}
   821		if s.BaseRef != "" && (s.Branch == "" || s.BaseRef != s.Branch) {
   822			if n, ok := gitCount(ctx, repoRoot, "rev-list", "--count", s.BaseRef+".."+headRef); ok {
   823				s.AheadCommits = n
   824			}
   825			if files := gitString(ctx, repoRoot, "diff", "--name-only", s.BaseRef+"..."+headRef); files != "" {
   826				s.FilesChanged = len(strings.Split(files, "\n"))
   827			}
   828		}
   829		if status := gitString(ctx, repoRoot, "status", "--porcelain"); status != "" {
   830			s.Uncommitted = len(strings.Split(status, "\n"))
   831		}
   832		return s, nil
   833	}
