   836	// origin/HEAD → origin/main → origin/master → local main → local master.
   837	// Returns "" if none match. Remote-tracking branches come first because they
   838	// reflect the team's convention; local branches are the fallback for repos
   839	// that haven't been `git fetch`'d recently.
   840	func detectBaseBranch(ctx context.Context, repoRoot string) string {
