   844	func detectBaseBranchRef(ctx context.Context, repoRoot string) baseBranchRef {
   845		if target := gitString(ctx, repoRoot, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); target != "" {
   846			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", target) {
   847				return baseBranchRef{display: strings.TrimPrefix(target, "origin/"), ref: target}
   848			}
   849		}
   850		candidates := []string{defaultBaseBranch, masterBaseBranch}
   851		for _, candidate := range candidates {
   852			ref := "origin/" + candidate
   853			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/remotes/"+ref) {
   854				return baseBranchRef{display: candidate, ref: ref}
   855			}
   856		}
   857		for _, candidate := range candidates {
   858			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/heads/"+candidate) {
   859				return baseBranchRef{display: candidate, ref: candidate}
   860			}
   861		}
   862		return baseBranchRef{}
   863	}
